    def check_dashboard_viewed_payload_fields(self, content: str) -> Tuple[bool, str]:
        """Verify dashboard_viewed payload has required fields."""
        required_fields = ['dashboard_id', 'view_duration_ms', 'card_count']

        # Try to extract DashboardViewedPayload type
        type_body = self.extract_type_body(content, 'DashboardViewedPayload')

        if not type_body:
            # Try other common naming patterns
            type_body = self.extract_type_body(content, 'DashboardViewedEvent')

        if not type_body:
            # Check if fields exist anywhere in the file as a fallback
            # This is PARTIAL coverage - we cannot determine if they belong to dashboard_viewed
            found_all = all(
                f"'{field}'" in content or f'"{field}"' in content
                for field in required_fields
            )
            if found_all:
                return False, 'dashboard_viewed payload type definition not found; field presence cannot be verified to belong to dashboard_viewed event'
            else:
                missing = [f for f in required_fields if f"'{f}'" not in content and f'"{f}"' not in content]
                return False, f'Required fields not found anywhere in file: {missing}'

        # Verify all required fields in the extracted type body
        for field in required_fields:
            if not self.check_field_in_body(type_body, field):
                return False, f'DashboardViewedPayload missing field: {field}'

        return True, f'dashboard_viewed payload has all required fields: {required_fields}'

