    def check_event_names_snake_case(self, content: str) -> Tuple[bool, str]:
        """Verify event names use snake_case convention."""
        required_event_names = ['dashboard_viewed', 'question_saved', 'filter_applied']
        found_count = 0

        for event_name in required_event_names:
            # Check for event name as string literal
            if f"'{event_name}'" in content or f'"{event_name}"' in content:
                found_count += 1

        if found_count < len(required_event_names):
            return False, f'Not all snake_case event names found: {found_count}/{len(required_event_names)}'

        return True, 'All event names use snake_case'

    def check_dashboard_viewed_payload_fields_snake_case(self, content: str) -> Tuple[bool, str]:
        """Verify dashboard_viewed payload field names use snake_case."""
        type_body = self.extract_type_body(content, 'DashboardViewedPayload')

        if not type_body:
            type_body = self.extract_type_body(content, 'DashboardViewedEvent')

        if not type_body:
            return False, 'DashboardViewedPayload type definition not found; cannot verify field naming'

        fields = self.extract_field_names_from_body(type_body)
        non_snake_case = [f for f in fields if not self.is_snake_case(f)]

        if non_snake_case:
            return False, f'DashboardViewedPayload has non-snake_case fields: {non_snake_case}'

        if not fields:
            return False, 'No fields found in DashboardViewedPayload'

        return True, f'All DashboardViewedPayload fields use snake_case: {fields}'

